mux.HandleFunc("GET /users/{id}", func(w http.ResponseWriter, r *http.Request) {
    u, err := users.Find(r.Context(), r.PathValue("id"))   // domain
    if errors.Is(err, domain.ErrNotFound) {
        http.Error(w, "not found", http.StatusNotFound)    // responder
        return
    }
    w.Header().Set("Content-Type", "application/json")
    json.NewEncoder(w).Encode(UserResponse{ID: u.ID, Name: u.Name})
})
